BEGIN;
SELECT pg_advisory_xact_lock(20261002,5000);
DO $$ BEGIN IF (SELECT COUNT(*) FROM residents)+(SELECT COUNT(*) FROM payments)+(SELECT COUNT(*) FROM cash_entries)+(SELECT COUNT(*) FROM loans)+(SELECT COUNT(*) FROM repayments)+(SELECT COUNT(*) FROM transfers)>0 THEN RAISE EXCEPTION 'Database tidak kosong. Impor dibatalkan.'; END IF; END $$;
COMMIT;
